            context: { ...context },
            fallbackAnchorElement: createFallbackAnchor(anchorElement),
            id: `card-action-popup-${this.nextId}`,
            kind: 'action',
            requestedActionId: null,
            requestedRunId: null,
        }
        this.nextId += 1
        this.setEntries([...this.entries,
